statement:
`expression` holds a single expression written in a tiny Lisp dialect. Evaluate it and return the integer it produces. An expression takes one of these forms:

- an integer literal, which may be negative;
- a variable: a lowercase letter followed by zero or more lowercase letters or digits (`let`, `add` and `mult` are never used as names); its value is the one from the innermost binding of that name currently in effect;
- `(add e1 e2)`: the sum of the values of its two sub-expressions;
- `(mult e1 e2)`: the product of the values of its two sub-expressions;
- `(let v1 e1 v2 e2 ... vn en expr)` with at least one pair: going left to right, each name `vi` is bound to the value of `ei` (later pairs can use earlier ones, and a name may be rebound), and the whole form is worth the value of the final `expr`.

Every `let` opens its own scope: its bindings hide outer bindings of the same names and vanish once its closing parenthesis is passed. The input is always a valid expression in which every variable is bound before it is read, and every value computed along the way fits in a signed 32-bit integer.

validator:
function validate([expression]) {
  if (typeof expression !== 'string' || expression.length < 1 || expression.length > 2000) return 'expression needs 1 to 2000 characters.';
  if (/^ | $| {2}/.test(expression)) return 'Separate tokens with single spaces and add none at the ends.';
  const tokens = expression.replaceAll('(', '( ').replaceAll(')', ' )').split(' ');
  const isName = token => /^[a-z][a-z0-9]*$/.test(token) && token !== 'let' && token !== 'add' && token !== 'mult';
  const scopes = [];
  let pos = 0;
  const fail = message => { throw new Error(message); };
  const fits = value => (value >= -(2 ** 31) && value < 2 ** 31 ? value : fail('Every value must fit in a signed 32-bit integer.'));
  const parse = () => {
    if (pos >= tokens.length) fail('The expression ends too early.');
    const token = tokens[pos++];
    if (/^-?\d+$/.test(token)) return fits(Number(token));
    if (isName(token)) {
      for (let i = scopes.length - 1; i >= 0; i--) if (scopes[i].has(token)) return scopes[i].get(token);
      return fail(`The variable ${token} is read before it is bound.`);
    }
    if (token !== '(') fail(`Unexpected token "${token}".`);
    const op = tokens[pos++];
    let value;
    if (op === 'add' || op === 'mult') {
      const a = parse(), b = parse();
      value = fits(op === 'add' ? a + b : a * b);
    } else if (op === 'let') {
      scopes.push(new Map());
      let pairs = 0;
      for (;;) {
        if (pos + 1 >= tokens.length) fail('The expression ends too early.');
        if (tokens[pos] === '(' || tokens[pos + 1] === ')') { value = parse(); break; }
        if (!isName(tokens[pos])) fail('Each let pair must start with a variable name.');
        const name = tokens[pos++];
        scopes[scopes.length - 1].set(name, parse());
        pairs++;
      }
      if (!pairs) fail('A let needs at least one variable and expression pair.');
      scopes.pop();
    } else fail('After "(" must come let, add or mult.');
    if (tokens[pos++] !== ')') fail('A form has the wrong number of parts or is not closed.');
    return value;
  };
  try {
    parse();
    if (pos !== tokens.length) return 'There is extra text after the expression.';
  } catch (error) {
    return error.message;
  }
  return null;
}

