function evaluate(expression) {
  const tokens = expression.replaceAll('(', '( ').replaceAll(')', ' )').split(' ');
  const scopes = [];
  let pos = 0;

  function lookup(name) {
    for (let i = scopes.length - 1; i >= 0; i--) {
      if (scopes[i].has(name)) {
        return scopes[i].get(name);
      }
    }
  }

  function parse() {
    const token = tokens[pos++];
    if (token !== '(') {
      return /[a-z]/.test(token[0]) ? lookup(token) : Number(token);
    }
    const op = tokens[pos++];
    let value;
    if (op === 'add') {
      const first = parse();
      value = first + parse();
    } else if (op === 'mult') {
      const first = parse();
      value = first * parse();
    } else {
      scopes.push(new Map());
      while (tokens[pos] !== '(' && tokens[pos + 1] !== ')') {
        const name = tokens[pos++];
        scopes[scopes.length - 1].set(name, parse());
      }
      value = parse();
      scopes.pop();
    }
    pos++;
    return value;
  }

  return parse();
}

