function evaluate(expression) {
  // Split the inside of a parenthesised form into its top-level parts by tracking depth.
  const split = body => {
    const parts = [];
    let depth = 0, start = 0;
    for (let i = 0; i <= body.length; i++) {
      if (i === body.length || (body[i] === ' ' && depth === 0)) { parts.push(body.slice(start, i)); start = i + 1; }
      else if (body[i] === '(') depth++;
      else if (body[i] === ')') depth--;
    }
    return parts;
  };
  // Each let works on a copy of the environment, so its bindings never leak outward.
  const run = (expr, env) => {
    if (expr[0] !== '(') return /^-?\d+$/.test(expr) ? parseInt(expr, 10) : env[expr];
    const parts = split(expr.slice(1, -1));
    if (parts[0] === 'add') return run(parts[1], env) + run(parts[2], env);
    if (parts[0] === 'mult') return run(parts[1], env) * run(parts[2], env);
    const inner = Object.assign(Object.create(null), env);
    for (let i = 1; i + 1 < parts.length; i += 2) inner[parts[i]] = run(parts[i + 1], inner);
    return run(parts[parts.length - 1], inner);
  };
  return run(expression, Object.create(null));
}

