function generate(rand, size) {
  const LIMIT = 2 ** 31 - 1;
  const large = size === 'large';
  const names = large ? ['x', 'y', 'z', 'a1', 'b2', 'cnt', 'tmp', 'v9', 'foo', 'bar'] : ['x', 'y', 'z', 'a1', 'b'];
  const pick = list => list[Math.floor(rand() * list.length)];
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const maxDepth = large ? 8 : 3;
  // Returns [text, value]; scope maps every visible name to its current value.
  const build = (depth, scope) => {
    const r = rand();
    if (depth > 0 && (depth >= maxDepth || r < 0.3)) {
      const bound = [...scope.keys()];
      if (bound.length && rand() < 0.6) { const name = pick(bound); return [name, scope.get(name)]; }
      const value = large ? int(-1000, 1000) : int(-9, 9);
      return [String(value), value];
    }
    if (r < 0.6) {
      const inner = new Map(scope);
      const pairs = int(1, large ? 4 : 3);
      let text = '(let';
      for (let i = 0; i < pairs; i++) {
        const name = pick(names);
        const [part, value] = build(depth + 1, inner);
        inner.set(name, value);
        text += ` ${name} ${part}`;
      }
      const [part, value] = build(depth + 1, inner);
      return [`${text} ${part})`, value];
    }
    const [left, a] = build(depth + 1, scope);
    const [right, b] = build(depth + 1, scope);
    if (rand() < 0.5 && Math.abs(a * b) <= LIMIT) return [`(mult ${left} ${right})`, a * b];
    if (Math.abs(a + b) <= LIMIT) return [`(add ${left} ${right})`, a + b];
    return [`(let ${pick(names)} ${left} ${right})`, b];
  };
  for (;;) {
    const [text] = build(0, new Map());
    if (large ? text.length >= 900 && text.length <= 2000 : text.length <= 200) return [text];
  }
}
